<?php $title="CBSE Important Links"; require "_top.php";
if(isset($_POST['delete'])){$pdo->prepare('DELETE FROM cbse_links WHERE id=?')->execute([(int)$_POST['delete']]);}
if(isset($_POST['save'])){$id=(int)($_POST['id']??0);if($id)$pdo->prepare('UPDATE cbse_links SET title=?,url=?,icon=?,sort_order=?,active=? WHERE id=?')->execute([$_POST['title'],$_POST['url'],$_POST['icon'],(int)$_POST['sort_order'],isset($_POST['active'])?1:0,$id]);else $pdo->prepare('INSERT INTO cbse_links(title,url,icon,sort_order,active) VALUES(?,?,?,?,?)')->execute([$_POST['title'],$_POST['url'],$_POST['icon'],(int)$_POST['sort_order'],isset($_POST['active'])?1:0]);}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM cbse_links WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$rows=$pdo->query('SELECT * FROM cbse_links ORDER BY sort_order,id')->fetchAll();
?>
<div class="panel"><h2><?= $edit?'Edit Link':'Add CBSE Important Link'?></h2><form method="post" class="form-grid"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label>Title<input name="title" required value="<?=e($edit['title']??'')?>"></label><label>Icon<input name="icon" value="<?=e($edit['icon']??'🔗')?>"></label><label class="full">Official URL<input name="url" type="url" required value="<?=e($edit['url']??'')?>"></label><label>Display Order<input name="sort_order" type="number" value="<?=e($edit['sort_order']??1)?>"></label><label class="check"><input type="checkbox" name="active" <?=($edit['active']??1)?'checked':''?>> Show on Home</label><button class="primary" name="save">Save Link</button></form></div>
<div class="table-wrap panel"><table><tr><th>Icon</th><th>Title</th><th>URL</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r): ?><tr><td><?=e($r['icon'])?></td><td><b><?=e($r['title'])?></b></td><td><?=e($r['url'])?></td><td><?= $r['active']?'Active':'Hidden'?></td><td><a href="?edit=<?=$r['id']?>">Edit</a> <form method="post" style="display:inline"><button class="link danger" name="delete" value="<?=$r['id']?>">Delete</button></form></td></tr><?php endforeach;?></table></div>
<?php require "_bottom.php"; ?>
